import React from 'react';
import type { Meta, StoryObj } from "@storybook/nextjs";
import { Grid } from "./Grid";
import { Box, Flex, Text } from "../index";

const meta: Meta<typeof Grid> = {
  title: "Design System/Atoms/Grid",
  component: Grid,
  parameters: {
    docs: {
      description: {
        component: `A CSS Grid layout component for creating responsive grid-based layouts. Wraps native CSS Grid with convenient props for columns, rows, and gap. Supports all standard CSS Grid features via the css prop.

**Features:**
- Simple API for common grid patterns
- Responsive column configurations
- Flexible gap sizing
- Full CSS Grid power via css prop
- Works seamlessly with design system tokens

**Common patterns:**
- \`columns="repeat(3, 1fr)"\` - 3 equal columns
- \`columns="repeat(auto-fit, minmax(250px, 1fr))"\` - Responsive auto-fit
- \`columns="200px 1fr"\` - Fixed + flexible columns
- \`gap="$md"\` - Gap using design system tokens

**Best practices:**
- Use auto-fit/auto-fill for responsive grids
- Set minmax() for flexible but bounded column sizes
- Use fr units for flexible columns
- Combine with Box or other components for grid items
- Consider using Flex for simple horizontal/vertical layouts`,
      },
    },
  },
  argTypes: {
    columns: {
      control: 'text',
      description: 'CSS grid-template-columns value (e.g., "repeat(3, 1fr)", "200px 1fr")',
      table: {
        type: { summary: 'string | number' },
      },
    },
    rows: {
      control: 'text',
      description: 'CSS grid-template-rows value (e.g., "100px auto", "repeat(3, 1fr)")',
      table: {
        type: { summary: 'string | number' },
      },
    },
    gap: {
      control: 'text',
      description: 'Gap between grid items (supports design tokens like "$md" or CSS values)',
      table: {
        type: { summary: 'string | number' },
      },
    },
    css: {
      control: 'object',
      description: 'Custom Stitches CSS styling for advanced grid configurations',
      table: {
        type: { summary: 'CSS' },
      },
    },
    children: {
      control: false,
      description: 'Grid items (children)',
      table: {
        type: { summary: 'ReactNode' },
      },
    },
  },
};

export default meta;
type Story = StoryObj<typeof Grid>;

